reference_solution:
def minmaxGasDist(stations, k):
    gaps = [stations[i + 1] - stations[i] for i in range(len(stations) - 1)]
    lo, hi = 0.0, float(max(gaps))
    while hi - lo > 1e-8:
        mid = (lo + hi) / 2
        need = sum(int(g / mid) for g in gaps)
        if need <= k:
            hi = mid
        else:
            lo = mid
    return hi

brute_force_solution:
def minmaxGasDist(stations, k):
    gaps = [stations[i + 1] - stations[i] for i in range(len(stations) - 1)]
    INF = float('inf')
    dp = [0.0] + [INF] * k
    for g in gaps:
        ndp = [INF] * (k + 1)
        for j in range(k + 1):
            for c in range(j + 1):
                if dp[j - c] < INF:
                    ndp[j] = min(ndp[j], max(dp[j - c], g / (c + 1)))
        dp = ndp
    return min(dp)

